func parseParts(t *testing.T, contentType string, body io.Reader) []*multipart.Part {
	t.Helper()

	mediaType, params, err := mime.ParseMediaType(contentType)
	if err != nil {
		t.Fatalf("parse content type: %v", err)
	}
	if mediaType != "multipart/form-data" {
		t.Fatalf("unexpected media type: %q", mediaType)
	}

	reader := multipart.NewReader(body, params["boundary"])
	var parts []*multipart.Part
	for {
		part, err := reader.NextPart()
		if errors.Is(err, io.EOF) {
			return parts
		}
		if err != nil {
			t.Fatalf("next part: %v", err)
		}
		data, err := io.ReadAll(part)
		if err != nil {
			t.Fatalf("read part: %v", err)
		}
		// Re-wrap so callers can read the part content again.
		parts = append(parts, &multipart.Part{Header: part.Header})
		partContents[len(parts)-1] = string(data)
	}
}

