type errReader struct{ err error }

func (r *errReader) Read([]byte) (int, error) { return 0, r.err }

type decodedPart struct {
	header  textproto.MIMEHeader
	content string
}

func (p decodedPart) formName() string {
	_, params, _ := mime.ParseMediaType(p.header.Get("Content-Disposition"))
	return params["name"]
}

func (p decodedPart) fileName() string {
	_, params, _ := mime.ParseMediaType(p.header.Get("Content-Disposition"))
	return params["filename"]
}

func decodeParts(t *testing.T, contentType string, body io.Reader) []decodedPart {
	t.Helper()

	mediaType, params, err := mime.ParseMediaType(contentType)
	if err != nil {
		t.Fatalf("parse content type: %v", err)
	}
	if mediaType != "multipart/form-data" {
		t.Fatalf("unexpected media type: %q", mediaType)
	}

	reader := multipart.NewReader(body, params["boundary"])
	var parts []decodedPart
	for {
		part, err := reader.NextPart()
		if errors.Is(err, io.EOF) {
			return parts
		}
		if err != nil {
			t.Fatalf("next part: %v", err)
		}
		data, err := io.ReadAll(part)
		if err != nil {
			t.Fatalf("read part: %v", err)
		}
		parts = append(parts, decodedPart{header: part.Header, content: string(data)})
	}
}

